local R=dofile('tests/kernel_billboards_harness.lua')
local n=0
local function case(name,fn)R.clientCase(name,fn);n=n+1 end
local function spawn(r,p)r.value=p or R.seed();return r.tick()end
local function count(t)local n=0;for _ in pairs(t)do n=n+1 end;return n end
case('empty idle',function(r)assert(r.tick()==1000 and count(r.duis)==0)end)
case('first frame DUI and two polygons',function(r)assert(spawn(r)==0 and count(r.duis)==1 and #r.polys==2);local p=r.polys[1];assert(p[1]==2 and p[2]==1.03 and p[3]==0 and p[14]=='forge_billboard_txd_1'and p[15]=='forge_billboard_tex_1'and p[16]==1 and p[17]==1);assert(r.polys[2][1]==0 and r.polys[2][3]==2)end)
case('reuse same URL/size',function(r)spawn(r);r.tick();assert(r.nextDui==201 and #r.polys==4)end)
case('far initial no DUI',function(r)local p=R.seed();p.billboards[1].vertices[1].x=999;assert(spawn(r,p)==1000 and count(r.duis)==0)end)
case('leaving range retains DUI',function(r)spawn(r);r.positions[11]=R.vector(999,0,0);assert(r.tick()==1000 and r.duis[201]);r.positions[11]=R.vector();r.tick();assert(r.nextDui==201)end)
case('world disabled destroys',function(r)spawn(r);local p=R.seed();p.enabled=false;r.apply(p);assert(count(r.duis)==0 and #r.billboards.entries==0 and r.tick()==1000)end)
case('board disabled destroys',function(r)spawn(r);local p=R.seed();p.billboards[1].enabled=false;r.apply(p);assert(count(r.duis)==0 and #r.billboards.entries==0)end)
case('nil payload clears',function(r)spawn(r);r.apply(nil);assert(not r.billboards.enabled and count(r.duis)==0)end)
case('bad entries ignored',function(r)r.apply({enabled='yes',billboards={{id='bad'},{url='x'}}});assert(#r.billboards.entries==0)end)
case('nonpositive numeric IDs kept client',function(r)local p=R.seed();p.billboards[1].id=0;spawn(r,p);assert(r.billboards.duis[0]and r.duis[201])end)
case('duplicate entries share/recreate ID',function(r)local p=R.seed();p.billboards[2]=R.H.copy(p.billboards[1]);p.billboards[2].url='fixture://other';spawn(r,p);assert(#r.billboards.entries==2 and r.nextDui==202);r.tick();assert(r.nextDui==204 and count(r.duis)==1)end)
case('change URL rebuild on draw not apply',function(r)spawn(r);local p=R.seed();p.billboards[1].url='fixture://new';r.apply(p);assert(r.duis[201]);r.tick();assert(not r.duis[201]and r.duis[202])end)
case('change width',function(r)spawn(r);local p=R.seed();p.billboards[1].width=900;r.apply(p);r.tick();assert(r.duis[202].width==900)end)
case('change height',function(r)spawn(r);local p=R.seed();p.billboards[1].height=900;r.apply(p);r.tick();assert(r.duis[202].height==900)end)
case('dimension floor/minimum client',function(r)local p=R.seed();p.billboards[1].width=-1;p.billboards[1].height=3.9;spawn(r,p);assert(r.duis[201].width==1 and r.duis[201].height==3)end)
case('dimension defaults',function(r)local p=R.seed();p.billboards[1].width=nil;p.billboards[1].height=nil;spawn(r,p);assert(r.duis[201].width==1920 and r.duis[201].height==1080)end)
case('empty URL destroys old no new',function(r)spawn(r);local p=R.seed();p.billboards[1].url='';r.apply(p);r.tick();assert(count(r.duis)==0 and r.nextDui==201 and #r.polys==2)end)
case('partial payload removes unseen IDs',function(r)spawn(r);r.apply({enabled=true,billboards={}});assert(count(r.duis)==0)end)
case('same id string texture naming mismatch retained',function(r)local p=R.seed();p.billboards[1].id='01';spawn(r,p);assert(r.billboards.duis[1]and r.polys[1][14]=='forge_billboard_txd_01')end)
case('degenerate geometry has no offset normal',function(r)local p=R.seed();p.billboards[1].vertices={};spawn(r,p);assert(r.polys[1][1]==0 and r.polys[1][2]==0 and r.polys[1][3]==0)end)
case('negative offset',function(r)local p=R.seed();p.billboards[1].offset=-0.1;spawn(r,p);assert(r.polys[1][2]==0.9)end)
case('reverse winding flips normal',function(r)local p=R.seed();local v=p.billboards[1].vertices;v[2],v[3]=v[3],v[2];spawn(r,p);assert(r.polys[1][2]==0.97)end)
case('older revisions not filtered',function(r)local p=R.seed();p.revision=10;r.apply(p);p=R.seed();p.revision=1;p.billboards={};r.apply(p);assert(#r.billboards.entries==0)end)
case('payload entries aliased',function(r)local p=R.seed();r.apply(p);assert(r.billboards.entries[1]==p.billboards[1]);r.billboards.setBillboardEnabled(1,false);assert(p.billboards[1].enabled==false)end)
case('set enabled false destroys immediately',function(r)spawn(r);r.billboards.setBillboardEnabled('1',false);assert(count(r.duis)==0 and not r.billboards.entries[1].enabled);r.tick();assert(count(r.duis)==0)end)
case('set true restores existing entry',function(r)spawn(r);r.billboards.setBillboardEnabled(1,false);r.billboards.setBillboardEnabled(1,true);r.tick();assert(r.duis[202])end)
case('set true cannot insert missing entry',function(r)r.apply({enabled=true,billboards={}});r.billboards.setBillboardEnabled(1,true);assert(#r.billboards.entries==0)end)
case('set strict true only',function(r)spawn(r);r.billboards.setBillboardEnabled(1,'true');assert(not r.billboards.entries[1].enabled and count(r.duis)==0);assert(r.billboards.setBillboardEnabled('bad',true)==nil)end)
case('create native zero retained as DUI record',function(r)r.duiZero=true;spawn(r);assert(r.billboards.duis[1].dui==0)end)
case('create exception before record',function(r)r.duiError=true;r.value=R.seed();assert(not pcall(r.tick)and count(r.billboards.duis)==0)end)
case('destroy exception retains record',function(r)spawn(r);r.destroyError=true;assert(not pcall(r.apply,nil)and r.billboards.duis[1])end)
case('unrelated stop ignored',function(r)spawn(r);r.stop('pr_bridge');assert(r.duis[201])end)
case('own stop destroys all known DUI',function(r)spawn(r);r.stop();assert(count(r.duis)==0 and count(r.billboards.duis)==0)end)
case('worker can recreate after simulated stop',function(r)spawn(r);r.stop();r.tick();assert(r.duis[202])end)
case('capture four corners serialized',function(r)local co=r.run(r.billboards.captureVertices);local ok,p=R.completeCapture(r,co);assert(ok and #p==4 and p[1].x==1.123 and p[1].y==2.235 and p[4].z==1.346 and not r.billboards.captureActive and not r.textui.IsTextUIOpen())end)
case('capture lock',function(r)local co=r.run(r.billboards.captureVertices);local ok,e=r.billboards.captureVertices();assert(not ok and e=='capture_active');r.just={[177]=true};assert(not r.resume(co))end)
for point=1,4 do case('cancel capture corner '..point,function(r)local co=r.run(r.billboards.captureVertices);for _=1,point-1 do r.just={[38]=true};assert(r.resume(co)==250);r.just={};assert(r.resume(co)==0)end;r.just={[177]=true};local ok,e=r.resume(co);assert(not ok and e=='cancelled'and not r.billboards.captureActive and not r.textui.IsTextUIOpen())end)end
case('capture no raycast clears lock',function(r)r.library.raycast=nil;local ok,e=r.billboards.captureVertices();assert(not ok and e=='raycast_unavailable'and not r.billboards.captureActive)end)
case('ray miss then cancel',function(r)r.rayMiss=true;local co=r.run(r.billboards.captureVertices);r.resume(co);r.just={[202]=true};assert(not r.resume(co))end)
case('ray error retains capture lock/text',function(r)r.shapeError=true;local co=r.run(r.billboards.captureVertices);assert(not pcall(r.resume,co)and r.billboards.captureActive and r.textui.IsTextUIOpen())end)
case('capture after resource stop',function(r)local co=r.run(r.billboards.captureVertices);r.stop();assert(r.billboards.captureActive);assert(R.completeCapture(r,co))end)
case('tune invalid parameter',function(r)local ok,e=r.billboards.fineTuneOffset(false);assert(not ok and e=='invalid_billboard')end)
case('tune capture lock',function(r)r.billboards.captureActive=true;local ok,e=r.billboards.fineTuneOffset(R.seed().billboards[1]);assert(not ok and e=='capture_active')end)
case('tune confirms offset and leaves DUI',function(r)local co=r.run(r.billboards.fineTuneOffset,R.seed().billboards[1]);local ok,v=r.finish(co);assert(ok and v==0.03 and count(r.duis)==1 and not r.textui.IsTextUIOpen())end)
case('tune canceled leaves DUI',function(r)local co=r.run(r.billboards.fineTuneOffset,R.seed().billboards[1]);local ok,e=r.finish(co,false);assert(not ok and e=='cancelled'and count(r.duis)==1)end)
case('tune disabled previews anyway',function(r)local p=R.seed().billboards[1];p.enabled=false;local co=r.run(r.billboards.fineTuneOffset,p);r.finish(co);assert(count(r.duis)==1 and not p.enabled)end)
case('tune up per frame',function(r)local co=r.run(r.billboards.fineTuneOffset,R.seed().billboards[1]);r.controls={[172]=true};r.resume(co);r.resume(co);local ok,v=r.finish(co);assert(ok and math.abs(v-0.035)<1e-8)end)
case('tune down per frame',function(r)local co=r.run(r.billboards.fineTuneOffset,R.seed().billboards[1]);r.controls={[173]=true};r.resume(co);local ok,v=r.finish(co);assert(ok and math.abs(v-0.0275)<1e-8)end)
case('tune controls precede Enter',function(r)local co=r.run(r.billboards.fineTuneOffset,R.seed().billboards[1]);r.controls={[172]=true};r.just={[201]=true};r.resume(co);assert(coroutine.status(co)=='suspended');r.finish(co)end)
case('tune upper clamp',function(r)local p=R.seed().billboards[1];p.offset=2;local co=r.run(r.billboards.fineTuneOffset,p);r.controls={[172]=true};r.resume(co);local ok,v=r.finish(co);assert(ok and v==2)end)
case('tune lower clamp',function(r)local p=R.seed().billboards[1];p.offset=-2;local co=r.run(r.billboards.fineTuneOffset,p);r.controls={[173]=true};r.resume(co);local ok,v=r.finish(co);assert(ok and v==-2)end)
case('tune and renderer simultaneous',function(r)spawn(r);local co=r.run(r.billboards.fineTuneOffset,R.seed().billboards[1]);r.resume(co);local before=#r.polys;r.tick();assert(#r.polys==before+2);r.finish(co,false)end)
case('tune stop does not cancel pending loop',function(r)local co=r.run(r.billboards.fineTuneOffset,R.seed().billboards[1]);r.resume(co);r.stop();assert(r.billboards.captureActive and count(r.duis)==0);r.finish(co);assert(count(r.duis)==1)end)
case('tune error retains lock/text',function(r)r.duiError=true;local co=r.run(r.billboards.fineTuneOffset,R.seed().billboards[1]);assert(not pcall(r.finish,co)and r.billboards.captureActive and r.textui.IsTextUIOpen())end)
print('PASS billboards renderer/DUI/capture/editor differentials '..n)
